<?php
require_once dirname(__DIR__).'/app/bootstrap.php';$activeNav='community';$uid=current_user_id();
if($_SERVER['REQUEST_METHOD']==='POST'){
 require_login(current_request_target());verify_csrf();$action=(string)($_POST['action']??'');
 if($action==='post'){$body=trim((string)($_POST['body']??''));$listingId=(int)($_POST['listing_id']??0);if(text_len($body)<8||text_len($body)>1800)flash('error','Write a post between 8 and 1,800 characters.');else{$check=$listingId?db()->prepare("SELECT id FROM listings WHERE id=:id AND status='published'"):null;if($check){$check->execute([':id'=>$listingId]);if(!$check->fetchColumn())$listingId=0;}db()->prepare('INSERT INTO community_posts(user_id,listing_id,body,status) VALUES(:u,:l,:b,\'pending\')')->execute([':u'=>$uid,':l'=>$listingId?:null,':b'=>$body]);flash('success','Your post was sent for community review. It will appear after approval.');}redirect(app_path('community-feed.php'));}
 if($action==='react'){$pid=(int)($_POST['post_id']??0);$s=db()->prepare("SELECT id FROM community_posts WHERE id=:p AND status='published'");$s->execute([':p'=>$pid]);if($s->fetchColumn()){db()->prepare('INSERT OR IGNORE INTO community_post_reactions(post_id,user_id,reaction) VALUES(:p,:u,\'like\')')->execute([':p'=>$pid,':u'=>$uid]);}redirect(app_path('community-feed.php'));}
 if($action==='comment'){$pid=(int)($_POST['post_id']??0);$body=trim((string)($_POST['body']??''));$s=db()->prepare("SELECT id FROM community_posts WHERE id=:p AND status='published'");$s->execute([':p'=>$pid]);if($s->fetchColumn()&&text_len($body)>=2&&text_len($body)<=600){db()->prepare('INSERT INTO community_post_comments(post_id,user_id,body) VALUES(:p,:u,:b)')->execute([':p'=>$pid,':u'=>$uid,':b'=>$body]);$postOwner=db()->prepare('SELECT user_id FROM community_posts WHERE id=:p');$postOwner->execute([':p'=>$pid]);$ownerId=(int)$postOwner->fetchColumn();if($ownerId!==$uid)notify_user($ownerId,'New comment on your community post','A member commented on your LocalGuide discovery.','community-feed.php');flash('success','Comment added.');}redirect(app_path('community-feed.php'));
 }
}
$posts=db()->query("SELECT p.*,u.name,u.username,l.name listing_name,l.slug listing_slug,(SELECT COUNT(*) FROM community_post_reactions r WHERE r.post_id=p.id) reaction_count,(SELECT COUNT(*) FROM community_post_comments c WHERE c.post_id=p.id AND c.status='published') comment_count FROM community_posts p JOIN users u ON u.id=p.user_id LEFT JOIN listings l ON l.id=p.listing_id WHERE p.status='published' ORDER BY p.created_at DESC LIMIT 50")->fetchAll();$pageTitle='Community feed | '.setting('site_name','LocalGuide');include __DIR__.'/includes/header.php';?>
<main id="main" class="container lg4-page"><div class="lg4-page-heading"><span class="lg4-eyebrow">THE NEIGHBOURHOOD, SHARED</span><h1>Local stories. Real people.</h1><p>Share a discovery, a helpful tip or a place the community should know about.</p><a class="button button-outline button-small" href="<?= app_path('community.php') ?>"><i class="fa-solid fa-arrow-left"></i> Community hub</a></div><div class="lg4-social-layout"><section class="lg4-social-feed"><div class="content-panel lg4-compose"><div class="lg4-compose-avatar"><?= $uid?h(text_upper(text_substr((string)(current_user()['name']??'U'),0,1))):'?' ?></div><div class="lg4-compose-body"><?php if(current_user()): ?><form method="post" class="studio-fields"><?= csrf_field() ?><input type="hidden" name="action" value="post"><label class="sr-only" for="postBody">Share something with the community</label><textarea id="postBody" name="body" rows="3" maxlength="1800" required placeholder="What local discovery would you like to share?"></textarea><label>Related place (optional)<select name="listing_id"><option value="0">No specific place</option><?php foreach(db()->query("SELECT id,name FROM listings WHERE status='published' ORDER BY name LIMIT 250")->fetchAll() as $l): ?><option value="<?= (int)$l['id'] ?>"><?= h($l['name']) ?></option><?php endforeach; ?></select></label><button class="button button-primary">Submit for review <i class="fa-solid fa-arrow-up"></i></button><small>Posts are reviewed before publication to protect the community.</small></form><?php else: ?><h3>Have a local tip to share?</h3><p>Sign in to contribute to the community feed.</p><a class="button button-primary" href="<?= h(auth_url(app_path('community-feed.php'),'login')) ?>">Sign in to post</a><?php endif; ?></div></div>
<?php if($posts): foreach($posts as $post): ?><article class="lg4-post-card" data-reveal="up"><div class="lg4-post-head"><span class="lg4-compose-avatar"><?= h(text_upper(text_substr((string)$post['name'],0,1))) ?></span><div><strong><?= h($post['name']) ?></strong><small>@<?= h($post['username']) ?> · <?= h(format_date($post['created_at'])) ?></small></div><?php if($post['listing_slug']): ?><a class="lg4-post-place" href="<?= app_path('index.php?listing='.rawurlencode($post['listing_slug'])) ?>"><i class="fa-solid fa-location-dot"></i> <?= h($post['listing_name']) ?></a><?php endif; ?></div><p class="lg4-post-body"><?= nl2br(h($post['body'])) ?></p><div class="lg4-post-actions"><?php if(current_user()): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="react"><input type="hidden" name="post_id" value="<?= (int)$post['id'] ?>"><button><i class="fa-regular fa-heart"></i> Appreciate · <?= (int)$post['reaction_count'] ?></button></form><?php else: ?><span><i class="fa-regular fa-heart"></i> <?= (int)$post['reaction_count'] ?> appreciations</span><?php endif; ?><span><i class="fa-regular fa-comment"></i> <?= (int)$post['comment_count'] ?> comments</span></div><?php $cs=db()->prepare("SELECT c.body,c.created_at,u.name FROM community_post_comments c JOIN users u ON u.id=c.user_id WHERE c.post_id=:p AND c.status='published' ORDER BY c.created_at ASC LIMIT 8");$cs->execute([':p'=>$post['id']]);$comments=$cs->fetchAll();if($comments): ?><div class="lg4-post-comments"><?php foreach($comments as $comment): ?><p><strong><?= h($comment['name']) ?></strong> <?= h($comment['body']) ?></p><?php endforeach; ?></div><?php endif; ?><?php if(current_user()): ?><form method="post" class="lg4-comment-form"><?= csrf_field() ?><input type="hidden" name="action" value="comment"><input type="hidden" name="post_id" value="<?= (int)$post['id'] ?>"><label class="sr-only" for="comment-<?= (int)$post['id'] ?>">Add a comment</label><input id="comment-<?= (int)$post['id'] ?>" name="body" maxlength="600" placeholder="Add a thoughtful comment…" required><button aria-label="Send comment"><i class="fa-solid fa-arrow-up"></i></button></form><?php endif; ?></article><?php endforeach; else: ?><div class="empty-state"><span><i class="fa-solid fa-users"></i></span><h3>The community feed is just getting started.</h3><p>Be the first to share a local discovery.</p></div><?php endif; ?></section><aside class="lg4-social-aside"><div class="content-panel"><span class="lg4-eyebrow">COMMUNITY GUIDELINES</span><h2>Keep it useful.</h2><ul><li>Share first-hand, helpful experiences.</li><li>Respect local people and businesses.</li><li>Do not publish private contact or personal information.</li><li>Disclose promotional relationships.</li><li>Reports are reviewed by moderators.</li></ul></div><div class="content-panel"><span class="lg4-eyebrow">DISCOVER MORE</span><a class="lg4-aside-link" href="<?= app_path('contributor.php') ?>"><i class="fa-solid fa-award"></i> Local contributors</a><a class="lg4-aside-link" href="<?= app_path('guide-ai.php') ?>"><i class="fa-solid fa-sparkles"></i> Guide AI</a><a class="lg4-aside-link" href="<?= app_path('events.php') ?>"><i class="fa-regular fa-calendar"></i> Community events</a></div></aside></div></main><?php include __DIR__.'/includes/footer.php';?>
